import{c as a,Q as s,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/zh-cn_image_0000002155016964.CXLggr3T.png",p="/assets/zh-cn_image_0000001819864122.2yUlPF9o.png",o="/assets/zh-cn_image_0000001820178290.B8sGyL5q.png",d="/assets/zh-cn_image_0000001866976705.D7mvhkSC.png",c="/assets/zh-cn_formulaimage_0000002105578933.XEfLwQP0.png",i="/assets/zh-cn_formulaimage_0000002069815092.DdVE9B3V.png",r="/assets/zh-cn_formulaimage_0000002105655005.B-jAls6q.png",u="/assets/AscendDequant%E5%86%85%E9%83%A8%E7%AE%97%E6%B3%95%E6%A1%86%E5%9B%BE.DPP5ho5l.png",T="/assets/AscendDequant-PER_TOKEN-PER_GROUP%E5%86%85%E9%83%A8%E7%AE%97%E6%B3%95%E6%A1%86%E5%9B%BE.CL9gYEmk.png",P=JSON.parse('{"title":"AscendDequant","description":"","frontmatter":{},"headers":[{"level":1,"title":"AscendDequant","slug":"ascenddequant"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"实现原理","slug":"实现原理"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/量化操作/AscendDequant.md","filePath":"api/SIMD-API/高阶API/量化操作/AscendDequant.md"}'),h={name:"api/SIMD-API/高阶API/量化操作/AscendDequant.md"};function _(m,t,g,f,b,C){return s(),n("div",null,[...t[0]||(t[0]=[e('<h1 id="ascenddequant" tabindex="-1">AscendDequant <a class="header-anchor" href="#ascenddequant" aria-label="Permalink to &quot;AscendDequant&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按元素做反量化计算，比如将int32_t数据类型反量化为half/float等数据类型。<strong>本接口最多支持输入为二维数据，不支持更高维度的输入。</strong></p><ul><li>假设输入srcTensor的shape为**（m, n）<strong>，每行数据（即n个输入数据）所占字节数要求</strong>32字节对齐**，每行中进行反量化的元素个数为<strong>calCount</strong>；</li><li>反量化系数deqScale可以为标量或者向量，为向量的情况下，calCount &lt;= deqScale的元素个数，只有前CalCount个反量化系数生效；</li><li>输出dstTensor的shape为**（m, n_dst）<strong>， n * sizeof(dstT)不满足32字节对齐时，需要</strong>向上补齐为32字节**，n_dst为向上补齐后的列数。</li></ul><p>下面通过两个具体的示例来解释参数的配置和计算逻辑（下文中DequantParams类型为存储shape信息的结构体{m, n, calCount}）：</p><ul><li><p>如下图示例中，srcTensor的数据类型为int32_t，m = 4，n = 8，calCount = 4，表明srcTensor中每行进行反量化的元素个数为4，deqScale中的前4个数生效，后12个数不参与反量化计算；dstTensor的数据类型为bfloat16_t，m = 4，n_dst = 16 (16 * sizeof(bfloat16_t) % 32 = 0)。计算逻辑是srcTensor的每n个数为一行，对于每行中的前calCount个元素，该行srcTensor的第i个元素与deqScale的第i个元素进行相乘写入dstTensor对应行的第i个元素，dstTensor对应行的第calCount + 1个元素~第n_dst个元素均为不确定的值。</p><p><img src="'+l+'" alt=""></p></li><li><p>如下示例中，srcTensor的数据类型为int32_t，m = 4，n = 8， calCount = 4，表明srcTensor中每行进行反量化的元素个数为4；dstTensor的数据类型为float，m = 4，n_dst = 8 (8 * sizeof(float) % 32 = 0)。对于srcTensor每行中的前4个元素都和标量deqScale相乘并写入dstTensor中每行的对应位置。</p><p><img src="'+p+'" alt=""></p></li></ul><p>当用户将模板参数中的mode配置为<strong>DEQUANT_WITH_SINGLE_ROW</strong>时：</p><p>针对DequantParams {m, n, calCount}， 若同时满足以下3个条件：</p><ol><li>m = 1</li><li>calCount为 32 / sizeof(dstT)的倍数</li><li>n % calCount = 0</li></ol><p>此时 {1, n, calCount}会被视作为** {n / calCount, calCount, calCount}** 进行反量化的计算。</p><p>具体效果可看下图所示，传入的DequantParams为 {1, 16, 8}。因为dstT为float，所以calCount满足为8的倍数，在<strong>DEQUANT_WITH_SINGLE_ROW</strong>模式下会将{1, 2 * 8, 8}转换为 {2, 8, 8}进行计算。</p><p><img src="'+o+'" alt=""></p><p><img src="'+d+'" alt=""></p><ul><li><p>PER_TOKEN反量化：srcTensor的每组token（token为n方向，共有m组token）中的元素共享一组deqscale参数，srcTensor为[m, n]时，deqscale为[m, 1]。</p><p><img src="'+c+'" alt=""></p></li><li><p>PER_GROUP反量化：这里定义group的计算方向为k方向，srcTensor在k方向上每groupSize个元素共享一组deqscale参数。srcTensor为[m, n]时，如果kDim=0，表示k是m方向，deqscale为[(m + groupSize - 1) / groupSize, n]；如果kDim=1，表示k是n方向，deqscale的shape为[m，(n + groupSize - 1) / groupSize]。</p><ul><li><p>kDim=0：</p><p><img src="'+i+'" alt=""></p></li><li><p>kDim=1：</p><p><img src="'+r+'" alt=""></p></li></ul></li></ul><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>以数据类型int32_t，shape为[m, n]的输入srcTensor，数据类型scaleT，shape为[n]的输入deqScale和数据类型dstT，shape为[m, n]的输出dstTensor为例，描述AscendDequant高阶API内部算法框图，如下图所示。</p><p><strong>图 1</strong> AscendDequant内部算法框图<br><img src="'+u+'" alt="" title="AscendDequant内部算法框图"></p><p>计算过程分为如下几步，均在Vector上进行：</p><ol><li>精度转换：将srcTensor和deqScale都转换成FP32精度的tensor，分别得到srcFP32和deqScaleFP32；</li><li>Mul计算：srcFP32一共有m行，每行长度为n；通过m次循环，将srcFP32的每行与deqScaleFP32相乘，通过mask控制仅对前dequantParams.calcount个数进行mul计算，图中index的取值范围为 [0, m)，对应srcFP32的每一行；计算所得结果为mulRes，shape为[m, n]；</li><li>结果数据精度转换：mulRes从FP32转换成dstT类型的tensor，所得结果为dstTensor，shape为[m, n]。</li></ol><p>PER_TOKEN/PER_GROUP场景下，输入srcTensor数据类型是int32_t/float，此时内部算法框图如下所示。</p><p><strong>图 2</strong> AscendDequant PER_TOKEN/PER_GROUP内部算法框图<br><img src="'+T+`" alt="" title="AscendDequant-PER_TOKEN-PER_GROUP内部算法框图"></p><p>PER_TOKEN/PER_GROUP场景的计算逻辑如下：</p><ol><li>读取数据：连续读取输入srcTensor；根据不同的场景，对输入deqscale，采用不同的读取方式；例如，PER_TOKEN场景做Broadcast处理，PER_GROUP场景做Gather处理；</li><li>精度转换：根据不同输入的数据类型组合，对srcTensor/deqscale进行相应的数据类型转换；</li><li>计算：对类型转换后的srcTensor和deqscale数据做乘法；</li><li>精度转换：将上述计算得到的结果转换成dstT类型，得到最终输出。</li></ol><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>反量化参数deqScale为矢量</p><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; deqScale, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, DequantParams params)</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; deqScale, DequantParams params)</span></span></code></pre></div></li><li><p>PER_TOKEN/PER_GROUP量化</p><p>仅支持Ascend 950PR/Ascend 950DT。</p><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename srcT, typename scaleT, const AscendDeQuantConfig&amp; config, const AscendDeQuantPolicy&amp; policy&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;srcT&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; scaleTensor, const LocalTensor&lt;scaleT&gt;&amp; offsetTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const AscendDeQuantParam&amp; para)</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename srcT, typename scaleT, const AscendDeQuantConfig&amp; config, const AscendDeQuantPolicy&amp; policy&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;srcT&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; scaleTensor, const LocalTensor&lt;scaleT&gt;&amp; offsetTensor, const AscendDeQuantParam&amp; para)</span></span></code></pre></div></li></ul></li></ul></li><li><p>反量化参数deqScale为标量</p><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const scaleT deqScale, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, DequantParams params)</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const scaleT deqScale, DequantParams params)</span></span></code></pre></div></li></ul></li></ul><p>由于该接口的内部实现中涉及复杂的数学计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式。</p><ul><li><p>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</p></li><li><p>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li></ul><p>接口框架申请的方式，开发者需要预留临时空间；通过sharedTmpBuffer传入的情况，开发者需要为sharedTmpBuffer申请空间。临时空间大小BufferSize的获取方式如下：通过<a href="./GetAscendDequantMaxMinTmpSize.html">GetAscendDequantMaxMinTmpSize</a>中提供的GetAscendDequantMaxMinTmpSize接口获取需要预留空间的范围大小。</p><p>以下接口不推荐使用，新开发内容不要使用如下接口：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; deqScale, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const uint32_t calCount)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; deqScale, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; deqScale, const uint32_t calCount)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename dstT, typename scaleT, DeQuantMode mode = DeQuantMode::DEQUANT_WITH_SINGLE_ROW&gt;</span></span>
<span class="line"><span>__aicore__ inline void AscendDequant(const LocalTensor&lt;dstT&gt;&amp; dstTensor, const LocalTensor&lt;int32_t&gt;&amp; srcTensor, const LocalTensor&lt;scaleT&gt;&amp; deqScale)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>dstT</td><td>目的操作数的数据类型。</td></tr><tr><td>scaleT</td><td>deqScale的数据类型。</td></tr><tr><td>mode</td><td>决定当DequantParams为{1, n, calCount}时的计算逻辑，传入enum DeQuantMode，支持以下 2 种配置：DEQUANT_WITH_SINGLE_ROW：当DequantParams {m, n, calCount} 同时满足以下条件：1、m = 1；2、calCount为 32 / sizeof(dstT)的倍数；3、n % calCount = 0时，即 {1, n, calCount} 会当作 {n / calCount, calCount, calCount} 进行计算。DEQUANT_WITH_MULTI_ROW：即使满足上述所有条件，{1, n, calCount} 依然只会当作 {1, n, calCount} 进行计算， 即总共n个数，前calCount个数进行反量化的计算。</td></tr></tbody></table><p><strong>表 2</strong> PER_TOKEN/PER_GROUP场景模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>srcT</td><td>源操作数的数据类型。</td></tr><tr><td>config</td><td>量化接口配置参数，AscendDeQuantConfig类型，定义如下方代码所示，其中参数的含义如下。 hasOffset：量化参数offset是否参与计算。True：表示offset参数参与计算。False：表示offset参数不参与计算。 kDim：group的计算方向，即k方向。仅在PER_GROUP场景有效，支持的取值如下。0：k轴是第0轴，即m方向为group的计算方向；1：k轴是第1轴，即n方向为group的计算方向。</td></tr><tr><td>policy</td><td>量化策略配置参数，AscendDeQuantPolicy 枚举类型，可取值如下： PER_TOKEN：配置为PER_TOKEN模式PER_GROUP：配置为PER_GROUP模式PER_CHANNEL_PER_GROUP：预留参数，暂不支持PER_TOKEN_PER_GROUP：预留参数，暂不支持}</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct AscendDeQuantConfig {</span></span>
<span class="line"><span>        bool hasOffset;</span></span>
<span class="line"><span>        int32_t kDim = 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>表 3</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。不同型号支持的数据类型请参考dstTensor支持的数据类型。 dstTensor的行数和srcTensor的行数保持一致。n * sizeof(dstT)不满足32字节对齐时，需要向上补齐为32字节，n_dst为向上补齐后的列数。如srcTensor数据类型为int32_t，shape为 (4, 8)，dstTensor为bfloat16_t，则n_dst应从8补齐为16，dstTensor shape为(4, 16)。补齐的计算过程为：n_dst = (8 * sizeof(bfloat16_t) + 32 - 1) / 32 * 32 / sizeof(bfloat16_t)。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。支持的数据类型为：int32_t。 shape为 [m, n]，n个输入数据所占字节数要求32字节对齐。</td></tr><tr><td>deqScale</td><td>输入</td><td>源操作数。类型为标量或者LocalTensor。类型为LocalTensor时，支持的TPosition为VECIN/VECCALC/VECOUT。不同型号支持的数据类型请参考deqScale支持的数据类型。 dstTensor、srcTensor、deqScale支持的数据类型组合请参考表5和表6。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。支持的数据类型为：uint8_t。 临时空间大小BufferSize的获取方式请参考GetAscendDequantMaxMinTmpSize。</td></tr><tr><td>params</td><td>输入</td><td>srcTensor的shape信息。DequantParams类型，定义如下方代码所示，其中参数的含义如下。 m：srcTensor的行数。n：srcTensor的列数。calCount：针对srcTensor每一行，前calCount个数为有效数据，与deqScale的前calCount个数或者deqScale标量进行乘法计算。 请注意： DequantParams.n * sizeof(T)必须是32字节的整数倍，T为srcTensor中元素的数据类型。因为是每n个数中的前calCount个数进行乘法运算，因此DequantParams.n和calCount需要满足以下关系 1 &lt;= DequantParams.calCount &lt;= DequantParams.n。 deqScale为矢量时，DequantParams.calCount &lt;= deqScale的元素个数。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct DequantParams</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint32_t m;      </span></span>
<span class="line"><span>    uint32_t n;     </span></span>
<span class="line"><span>    uint32_t calCount; </span></span>
<span class="line"><span>};</span></span></code></pre></div><p><strong>表 4</strong> PER_TOKEN/PER_GROUP场景接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。支持的数据类型为：half、bfloat16_t、float。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。支持的数据类型为：int32_t、float。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。支持的数据类型为：uint8_t。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 临时空间大小BufferSize的获取方式请参考GetAscendQuantMaxMinTmpSize。</td></tr><tr><td>scaleTensor</td><td>输入</td><td>量化参数scale。支持的数据类型为：half、bfloat16_t、float。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>offsetTensor</td><td>输入</td><td>量化参数offset。支持的数据类型和scaleTensor保持一致。预留参数，当前暂不支持。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>para</td><td>输入</td><td>反量化接口的参数，定义如下方代码所示，其中参数的含义如下。 m：m方向元素个数。n：n方向元素个数。n值对应的数据大小需满足32B对齐的要求，即shape最后一维为n的输入输出均需要满足该维度上32B对齐的要求。calCount:参与计算的元素个数。calCount必须是n的整数倍。groupSize ：PER_GROUP场景有效，表示groupSize行/列数据共用一个scale/offset。groupSize的取值必须大于0且是32的整倍数。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct AscendDeQuantParam {</span></span>
<span class="line"><span>        uint32_t m;</span></span>
<span class="line"><span>        uint32_t n;</span></span>
<span class="line"><span>        uint32_t calCount;   </span></span>
<span class="line"><span>        uint32_t groupSize = 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>表 5</strong> 支持的数据类型组合（deqScale为LocalTensor）</p><table tabindex="0"><thead><tr><th>dstTensor</th><th>srcTensor</th><th>deqScale</th></tr></thead><tbody><tr><td>half</td><td>int32_t</td><td>uint64_t 注意：当deqScale的数据类型是uint64_t时，数值低32位是参与计算的数据，数据类型是float，数值高32位是一些控制参数，本接口不使用。</td></tr><tr><td>float</td><td>int32_t</td><td>float</td></tr><tr><td>float</td><td>int32_t</td><td>bfloat16_t</td></tr><tr><td>bfloat16_t</td><td>int32_t</td><td>bfloat16_t</td></tr><tr><td>bfloat16_t</td><td>int32_t</td><td>float</td></tr></tbody></table><p><strong>表 6</strong> 支持的数据类型组合（deqScale为标量）</p><table tabindex="0"><thead><tr><th>dstTensor</th><th>srcTensor</th><th>deqScale</th></tr></thead><tbody><tr><td>bfloat16_t</td><td>int32_t</td><td>bfloat16_t</td></tr><tr><td>bfloat16_t</td><td>int32_t</td><td>float</td></tr><tr><td>float</td><td>int32_t</td><td>bfloat16_t</td></tr><tr><td>float</td><td>int32_t</td><td>float</td></tr></tbody></table><p><strong>表 7</strong> PER_TOKEN/PER_GROUP场景支持的数据类型组合</p><table tabindex="0"><thead><tr><th>srcDtype</th><th>scaleDtype</th><th>dstDtype</th></tr></thead><tbody><tr><td>int32_t</td><td>half</td><td>half</td></tr><tr><td>int32_t</td><td>bfloat16_t</td><td>bfloat16_t</td></tr><tr><td>int32_t</td><td>float</td><td>float</td></tr><tr><td>int32_t</td><td>float</td><td>half</td></tr><tr><td>int32_t</td><td>float</td><td>bfloat16_t</td></tr><tr><td>float</td><td>half</td><td>half</td></tr><tr><td>float</td><td>bfloat16_t</td><td>bfloat16_t</td></tr><tr><td>float</td><td>float</td><td>float</td></tr><tr><td>float</td><td>float</td><td>half</td></tr><tr><td>float</td><td>float</td><td>bfloat16_t</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p><strong>不支持源操作数与目的操作数地址重叠。</strong></p></li><li><p>操作数地址对齐要求请参见<a href="./../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>PER_TOKEN/PER_GROUP场景，连续计算方向（即n方向）的数据量要求32B对齐。</p></li><li><p>非PER_TOKEN/PER_GROUP场景dstTensor支持的数据类型</p><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：half、bfloat16_t、float。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half、bfloat16_t、float。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half、bfloat16_t、float。</p><p>Atlas 推理系列产品AI Core，支持的数据类型为：half、float。</p><p>Kirin X90，支持的数据类型为：half、float。</p><p>Kirin 9030，支持的数据类型为：half、float。</p></li><li><p>非PER_TOKEN/PER_GROUP场景deqScale支持的数据类型</p><p>Ascend 950PR/Ascend 950DT，当deqScale为矢量时，支持的数据类型为：uint64_t、float、bfloat16_t；当deqScale为标量时，支持的数据类型为bfloat16_t、float。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，当deqScale为矢量时，支持的数据类型为：uint64_t、float、bfloat16_t；当deqScale为标量时，支持的数据类型为bfloat16_t、float。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，当deqScale为矢量时，支持的数据类型为：uint64_t、float、bfloat16_t；当deqScale为标量时，支持的数据类型为bfloat16_t、float。</p><p>Atlas 推理系列产品AI Core，当deqScale为矢量时，支持的数据类型为：uint64_t、float；当deqScale为标量时，支持的数据类型为float。</p><p>Kirin X90，当deqScale为矢量时，支持的数据类型为：uint64_t、float；当deqScale为标量时，支持的数据类型为float。</p><p>Kirin 9030，当deqScale为矢量时，支持的数据类型为：uint64_t、float；当deqScale为标量时，支持的数据类型为float。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放反量化计算的结果Tensor</span></span>
<span class="line"><span>// srcLocal: 存放反量化计算的输入Tensor</span></span>
<span class="line"><span>// deqScaleLocal: 存放反量化计算量反量化系数的输入Tensor</span></span>
<span class="line"><span>// sharedTmpBuffer: 存放反量化计算过程中临时缓存的Tensor</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uint32_t m = 4;  // srcTensor的行数</span></span>
<span class="line"><span>uint32_t n = 8;  // srcTensor的列数</span></span>
<span class="line"><span>uint32_t calCount = 6;  // 每行srcTensor的前calCount个数参与反量化计算</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 反量化参数deqScale为矢量，通过sharedTmpBuffer入参传入临时空间。</span></span>
<span class="line"><span>AscendC::AscendDequant(dstLocal, srcLocal, deqScaleLocal, sharedTmpBuffer, {m, n, calCount});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 反量化参数deqScale为矢量，通过接口框架申请临时空间。</span></span>
<span class="line"><span>AscendC::AscendDequant(dstLocal, srcLocal, deqScaleLocal, {m, n, calCount});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 反量化参数deqScale为标量，通过sharedTmpBuffer入参传入临时空间。</span></span>
<span class="line"><span>AscendC::AscendDequant(dstLocal, srcLocal, static_cast&lt;float&gt;(2.2), sharedTmpBuffer, {m, n, calCount});</span></span>
<span class="line"><span>// 反量化参数deqScale为标量，通过接口框架申请临时空间。</span></span>
<span class="line"><span>AscendC::AscendDequant(dstLocal, srcLocal, static_cast&lt;float&gt;(2.2), {m, n, calCount});</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal) int32_t数据类型:</span></span>
<span class="line"><span>[[-16 -15 -14 -13 -12 -11 -10  -9]</span></span>
<span class="line"><span> [ -8  -7  -6  -5  -4  -3  -2  -1]</span></span>
<span class="line"><span> [  0   1   2   3   4   5   6   7]</span></span>
<span class="line"><span> [  8   9  10  11  12  13  14  15]]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>反量化参数deqScaleLocal float数据类型:</span></span>
<span class="line"><span>[2.2  -2.2  2.2  -2.2  2.2  -2.2  0.  0.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出数据(dstLocal) float数据类型:</span></span>
<span class="line"><span>[[-35.2  33.  -30.8  28.6 -26.4  24.2 -10.   -9. ]</span></span>
<span class="line"><span> [-17.6  15.4 -13.2  11.   -8.8   6.6  -2.   -1. ]</span></span>
<span class="line"><span> [  0.   -2.2   4.4  -6.6   8.8 -11.    6.    7. ]</span></span>
<span class="line"><span> [ 17.6 -19.8  22.  -24.2  26.4 -28.6  14.   15. ]]</span></span></code></pre></div><p>PER_TOKEN/PER_GROUP场景调用示例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 注意m,n需从外部传入</span></span>
<span class="line"><span>constexpr static bool isReuseSource = false;</span></span>
<span class="line"><span>constexpr static AscendDeQuantConfig config = {has_offset, -1};</span></span>
<span class="line"><span>constexpr static AscendDeQuantPolicy policy = AscendDeQuantPolicy::PER_TOKEN; // 可修改枚举值以使能PER_GROUP</span></span>
<span class="line"><span>AscendDeQuantParam para;</span></span>
<span class="line"><span>para.m = m;</span></span>
<span class="line"><span>para.n = n;</span></span>
<span class="line"><span>para.calCount = calCount;</span></span>
<span class="line"><span>AscendDequant&lt;dstType, srcType, scaleType, config, policy&gt;(dstLocal, srcLocal, scaleLocal, offsetLocal, para);</span></span></code></pre></div>`,63)])])}const A=a(h,[["render",_]]);export{P as __pageData,A as default};
